---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Top pages: Most visited pages with share of traffic and a quick sort.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change top-pages.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './top-pages.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="top-pages" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="tpx panel">
  <div class="tpx-h"><div><b>Top pages</b><span class="muted tpx-sub"><span class="num tpx-tot">0</span> views, last 30 days</span></div><div class="seg2 tpx-sg" role="group" aria-label="Sort"><button aria-pressed="true" data-v="v">Views</button><button aria-pressed="false" data-v="c">Change</button></div></div>
  <div class="tpx-list"></div>
</div>
  </Fragment></div>
</div>
<script>
  import './top-pages.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Top pages ---------- */
.tpx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:10px}
.tpx-h{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;padding:0 2px}
.tpx-h>div:first-child{display:flex;flex-direction:column;font-size:13.5px}
.tpx-h b{font-weight:500}
.tpx-sub{font-size:12px}
.tpx-sg button{font-size:12px;height:26px;padding:0 9px}
.tpx-list{position:relative;height:calc(6 * 50px)}
.tpx-r{position:absolute;left:0;right:0;height:46px;display:grid;grid-template-columns:20px 1fr 56px 60px;align-items:start;gap:10px;padding:9px var(--dm-s-2) 0;border-radius:var(--dm-r-in);transition:transform .55s var(--dm-ease),background .2s}
@media (hover:hover) and (pointer:fine){.tpx-r:hover{background:var(--dm-row)}}
.tpx-r .rk{font-family:var(--dm-mono);font-size:11px;line-height:19.5px;color:var(--dm-muted);text-align:center;transition:color .2s}
@media (hover:hover) and (pointer:fine){.tpx-r:hover .rk{color:var(--dm-fg)}}
.tpx-r .pg{display:flex;flex-direction:column;gap:5px;min-width:0}
.tpx-r .p{font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tpx-r .tr{height:4px;border-radius:2px;background:var(--dm-chip);overflow:hidden}
@media (hover:hover) and (pointer:fine){.tpx-r:hover .tr{background:var(--dm-surface)}}
.tpx-r .tr i{display:block;height:100%;width:0;border-radius:2px;background:var(--dm-accent-mark,var(--dm-accent));transition:width .9s var(--dm-ease)}
.tpx-r .n{font-size:13px;font-weight:500;min-width:52px;text-align:right}
.tpx-r .ch{justify-self:end;padding:0 6px}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, seg, tween } from '../core/core.js';
DM.def('top-pages', (r, c) => {
  const P = [['/pricing','Pricing',18420,24],['/','Home',15210,3],['/components','Components',9870,41],['/docs/agent','Agent docs',6340,-8],['/blog/soft-ui','Soft UI, the post',4120,112],['/changelog','Changelog',2210,-14]];
  const list = $('.tpx-list', r), mx = P[0][2], tot = P.reduce((a, p) => a + p[2], 0), H = 50;
  list.innerHTML = P.map(p => `<div class="tpx-r" data-tip="designme.dev${p[0]}"><span class="rk"></span><span class="pg"><span class="p">${p[1]} <span class="muted">${p[0]}</span></span><span class="tr"><i></i></span></span><span class="n num">${p[2].toLocaleString('en-US')}</span><span class="tag ch num ${p[3] >= 0 ? 'ok' : 'bad'}">${p[3] >= 0 ? '+' : '−'}${Math.abs(p[3])}%</span></div>`).join('');
  const rows = $$('.tpx-r', list);
  function sort(k){
    const order = [...P].sort((a, b) => k === 'v' ? b[2] - a[2] : b[3] - a[3]);
    rows.forEach((row, i) => { const j = order.indexOf(P[i]); row.style.transform = `translateY(${j * H}px)`; $('.rk', row).textContent = j + 1; });
  }
  sort('v'); rows.forEach((row, i) => row.animate([{ opacity:0, filter:'blur(4px)' }, { opacity:1, filter:'blur(0)' }], { duration:450, delay:i * 50, easing:'ease-out', fill:'backwards' }));
  rows.forEach((row, i) => c.later(300 + i * 70, () => $('.tr i', row).style.width = P[i][2] / mx * 100 + '%'));
  $('.tpx-tot', r).textContent = '0';
  c.later(260, () => tween(0, tot, 1000, v => $('.tpx-tot', r).textContent = Math.round(v).toLocaleString('en-US')));
  seg($('.tpx-sg', r), sort);
});
